begin;
create temporary table coding_question_seed(collection_slug text not null,slug text not null,title text not null,problem_statement text not null,difficulty text not null,topic_tags text[] not null,constraints jsonb not null,examples jsonb not null,starter_code_by_language jsonb not null,points integer not null) on commit drop;
insert into coding_question_seed select collection_slug,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points from jsonb_to_recordset($seed$[{"collection_slug":"csharp-programming","slug":"password-rule-codes-csharp","title":"Password Rule Codes","problem_statement":"Return failing rules in order: length if fewer than 10 characters, upper if no uppercase ASCII, lower if no lowercase ASCII, digit if no ASCII digit, symbol if no letter-or-digit ASCII symbol. Report every failure once.","difficulty":"Medium","topic_tags":["Validation and Collections","C#"],"constraints":["Password length is at most 100000 UTF-16 code units.","The character classes are ASCII uppercase, lowercase, digits, and non-alphanumeric ASCII symbols."],"examples":[{"input":"\"abc\"","output":"[\"length\",\"upper\",\"digit\",\"symbol\"]"},{"input":"\"Abcdef123!\"","output":"[]"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static List<string> PasswordRuleCodes(string password) {\n    // Password Rule Codes.\n    return new List<string>();\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"normalize-email-csharp","title":"Normalize an Email Address","problem_statement":"Trim outer whitespace and lowercase invariantly. Return null unless there is exactly one @, nonempty local and domain parts, no internal whitespace, and at least one dot in the domain.","difficulty":"Medium","topic_tags":["Validation and Culture","C#"],"constraints":["Input may be null and otherwise contains at most 10000 characters.","Use invariant case conversion; require exactly one @, nonempty parts, and a dotted domain."],"examples":[{"input":"\" Ada@Example.COM \"","output":"\"ada@example.com\""},{"input":"\"a @b.com\"","output":"null"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static string? NormalizeEmail(string? email) {\n    // Normalize an Email Address.\n    return null;\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"parse-settings-unique-csharp","title":"Parse Unique Settings","problem_statement":"Parse nonblank KEY=VALUE lines, trimming both sides. Keys use ASCII letters, digits, or underscore and must be unique; any malformed line fails with an empty result.","difficulty":"Medium","topic_tags":["Parsing and Errors","C#"],"constraints":["At most 10000 lines; blank lines are ignored and keys are ordinal case-sensitive.","Malformed lines, invalid keys, or duplicate keys fail atomically with an empty dictionary."],"examples":[{"input":"[\"HOST = api\",\"PORT=8080\"]","output":"true,{HOST:api,PORT:8080}"},{"input":"[\"A=1\",\"A=2\"]","output":"false,{}"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static bool TryParseSettings(string[] lines, out Dictionary<string,string> settings) {\n    // Parse Unique Settings.\n    settings = new Dictionary<string,string>(); return false;\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"compare-semantic-versions-csharp","title":"Compare Version Components","problem_statement":"Compare dot-separated nonnegative integer components numerically, treating missing trailing components as zero. Inputs are valid and each component fits Int32; return -1, 0, or 1.","difficulty":"Medium","topic_tags":["Parsing and Comparison","C#"],"constraints":["Each version has at least one dot-separated component; components fit Int32.","Compare component values, not textual width; omitted trailing components are zero."],"examples":[{"input":"\"1.02\",\"1.2.0\"","output":"0"},{"input":"\"2.10\",\"2.9\"","output":"1"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static int CompareVersions(string left, string right) {\n    // Compare Version Components.\n    return 0;\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"invoice-total-decimal-csharp","title":"Compute Invoice Total","problem_statement":"Sum price times quantity with decimal arithmetic. Throw ArgumentOutOfRangeException for a negative price or quantity; an empty invoice totals zero.","difficulty":"Medium","topic_tags":["Value Types and Decimal","C#"],"constraints":["Each quantity is a nonnegative Int32 and each price is a nonnegative decimal.","Calculate every line and total using decimal arithmetic; empty input totals zero."],"examples":[{"input":"[(2.50,2),(1.25,4)]","output":"10.00"},{"input":"[(3.25,2)]","output":"6.50"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static decimal InvoiceTotal((decimal Price,int Quantity)[] lines) {\n    // Compute Invoice Total.\n    return 0m;\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"inventory-reconciliation-csharp","title":"Reconcile Inventory Counts","problem_statement":"For each SKU, compute opening plus received minus shipped. Return SKUs whose computed count differs from closing count, preserving row order. All counts are nonnegative.","difficulty":"Medium","topic_tags":["Tuples and Domain Modeling","C#"],"constraints":["Each SKU appears at most once; all inventory quantities are nonnegative Int32 values.","Expected quantity is Opening + Received - Shipped; preserve source order for mismatches."],"examples":[{"input":"[(A,10,5,7,8),(B,4,0,1,4)]","output":"[\"B\"]"},{"input":"[(X,0,3,1,2)]","output":"[]"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static List<string> InventoryMismatches((string Sku,int Opening,int Received,int Shipped,int Closing)[] rows) {\n    // Reconcile Inventory Counts.\n    return new List<string>();\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"region-revenue-linq-csharp","title":"Revenue by Region","problem_statement":"Group sales by region using ordinal case-insensitive keys, sum decimal amounts, and use the lowercase invariant region as each result key.","difficulty":"Medium","topic_tags":["LINQ and Grouping","C#"],"constraints":["At most 100000 sales; region labels are nonempty and amounts are decimal.","Group with ordinal case-insensitive comparison and emit lowercase invariant keys."],"examples":[{"input":"[(West,12.5),(west,7.5),(East,4)]","output":"{west:20.0,east:4}"},{"input":"[(North,0)]","output":"{north:0}"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static Dictionary<string,decimal> RevenueByRegion((string Region,decimal Amount)[] sales) {\n    // Revenue by Region.\n    return new Dictionary<string,decimal>();\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"consolidate-value-key-cart-lines-csharp","title":"Consolidate Cart Lines by Value Key","problem_statement":"Combine cart lines that have the same SKU using ordinal case-sensitive string equality and the same decimal unit price. Sum quantities with checked arithmetic, preserve the first occurrence order of each distinct (SKU, price) value key, and return a new list.","difficulty":"Medium","topic_tags":["Value Semantics","Collections","C#"],"constraints":["At most 100000 lines; SKU strings are non-null, prices are nonnegative decimals, and quantities are nonnegative integers.","Tuple key equality uses SKU value and decimal numeric value; quantity totals must fit Int32."],"examples":[{"input":"[(pen,1.25,2),(book,3.00,1),(pen,1.25,3)]","output":"[(pen,1.25,5),(book,3.00,1)]"},{"input":"[(pen,1.25,1),(pen,1.50,1)]","output":"[(pen,1.25,1),(pen,1.50,1)]"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static List<(string Sku,decimal Price,int Quantity)> ConsolidateCartLines((string Sku,decimal Price,int Quantity)[] lines) {\n    // Consolidate by tuple value equality in first-seen order.\n    return new List<(string Sku,decimal Price,int Quantity)>();\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"preorder-tree-values-csharp","title":"Preorder Tree Values","problem_statement":"TreeNode exposes Value, Left, and Right. Return node values root-left-right; null root produces an empty list.","difficulty":"Medium","topic_tags":["Trees and Recursion","C#"],"constraints":["The tree has at most 100000 nodes and contains no cycles.","Visit root before left subtree before right subtree; null root is an empty traversal."],"examples":[{"input":"root 4; left 2; right 7; left child of 2 is 1","output":"[4,2,1,7]"},{"input":"root=-2; left=-5","output":"[-2,-5]"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic sealed class TreeNode { public int Value; public TreeNode? Left, Right; }\npublic static class Solution {\n  public static List<int> Preorder(TreeNode? root) {\n    // Preorder Tree Values.\n    // Traverse root, left, then right.\n    return new List<int>();\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"best-offer-selection-csharp","title":"Choose the Best Valid Offer","problem_statement":"An offer is eligible when its region is null or matches region ordinally ignoring case, and its expiry is null or later than now. Choose the lowest price per SKU; ties prefer a regional offer, then source order. Return results by ordinal SKU.","difficulty":"Medium","topic_tags":["LINQ, Nullability, and Ordering","C#"],"constraints":["Offer price is nonnegative; expiry null means no expiration, otherwise eligibility requires ExpiresAt > now.","Region matching is ordinal case-insensitive; a regional offer wins an equal-price tie over a global offer."],"examples":[{"input":"offers=[(A,12,West,null),(A,10,null,null),(B,7,west,11:00)], region=West, now=10:00","output":"[(A,10),(B,7)]"},{"input":"offers=[(X,5,null,null),(X,5,West,null)], region=West, now=10:00","output":"[(X,5)]"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static List<(string Sku,decimal Price)> BestOffers((string Sku,decimal Price,string? Region,DateTimeOffset? ExpiresAt)[] offers,string region,DateTimeOffset now) {\n    // Choose the Best Valid Offer.\n    return new List<(string Sku,decimal Price)>();\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"largest-remainder-cent-allocation-csharp","title":"Allocate Cents by Largest Remainder","problem_statement":"Allocate nonnegative integer cents proportionally to nonnegative decimal weights. Floor each exact share, then distribute remaining cents by descending fractional remainder, breaking ties by lower input index. Weights have positive total.","difficulty":"Hard","topic_tags":["Decimal Arithmetic and Deterministic Ties","C#"],"constraints":["totalCents is nonnegative; weights are nonnegative decimals with positive sum.","Return one nonnegative integer allocation per weight and allocate every cent exactly once."],"examples":[{"input":"total=10, weights=[0.5,0.3,0.2]","output":"[5,3,2]"},{"input":"total=2, weights=[0.5,0.5,0]","output":"[1,1,0]"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static int[] AllocateCents(int totalCents,decimal[] weights) {\n    // Allocate Cents by Largest Remainder.\n    return Array.Empty<int>();\n  }\n}"},"points":200},{"collection_slug":"csharp-programming","slug":"business-day-calendar-csharp","title":"Find Business Days","problem_statement":"Starting at start, return count dates that are Monday through Friday and not in holidays. Include start if it qualifies; advance one calendar day at a time.","difficulty":"Medium","topic_tags":["DateOnly and Collections","C#"],"constraints":["0 <= count <= 100000; holidays is a set of valid DateOnly values.","Weekends are Saturday and Sunday; a holiday excludes a weekday but does not change the calendar progression."],"examples":[{"input":"start=2025-01-03,count=3,holidays=[2025-01-06]","output":"[2025-01-03,2025-01-07,2025-01-08]"},{"input":"start=2025-01-04,count=2,holidays=[]","output":"[2025-01-06,2025-01-07]"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static List<DateOnly> NextBusinessDays(DateOnly start,int count,HashSet<DateOnly> holidays) {\n    // Find Business Days.\n    return new List<DateOnly>();\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"known-permission-bits-csharp","title":"Decode Known Permission Bits","problem_statement":"Return enabled known positive power-of-two bits sorted ascending. Ignore duplicate or invalid entries in knownBits.","difficulty":"Medium","topic_tags":["Enums and Bitwise Operations","C#"],"constraints":["Known bit values are arbitrary Int32 values and mask is an Int32.","Only positive powers of two enabled in mask are returned, once each in ascending order."],"examples":[{"input":"mask=13,known=[1,2,4,8,4,0]","output":"[1,4,8]"},{"input":"mask=6,known=[1,2,4]","output":"[2,4]"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static int[] EnabledKnownBits(int mask,int[] knownBits) {\n    // Decode Known Permission Bits.\n    return Array.Empty<int>();\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"invariant-decimal-parse-csharp","title":"Parse Invariant Decimal","problem_statement":"Accept optional sign and decimal point using invariant culture only; reject commas and surrounding whitespace. On failure set value to zero.","difficulty":"Medium","topic_tags":["Parsing and Culture","C#"],"constraints":["Text has at most 128 characters; parsed value must fit Decimal.","Only invariant sign and decimal-point syntax is accepted; failure sets value to zero."],"examples":[{"input":"\"-12.50\"","output":"true,-12.50"},{"input":"\"1,200\"","output":"false,0"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static bool TryParseInvariantDecimal(string text,out decimal value) {\n    // Parse Invariant Decimal.\n    value = 0m; return false;\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"valid-date-range-csharp","title":"Validate Inclusive Date Range","problem_statement":"A date range is valid when start is not after end and the inclusive span is at most 366 days. Count both endpoints when measuring the span.","difficulty":"Easy","topic_tags":["DateOnly and Validation","C#"],"constraints":["DateOnly values are valid Gregorian calendar dates.","The range is inclusive, ordered, and has no more than 366 days."],"examples":[{"input":"2024-01-01,2024-12-31","output":"true"},{"input":"2024-02-02,2024-02-01","output":"false"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static bool IsValidDateRange(DateOnly start,DateOnly end) {\n    // Validate Inclusive Date Range.\n    return false;\n  }\n}"},"points":100},{"collection_slug":"csharp-programming","slug":"batch-enumerable-csharp","title":"Batch a Single-Pass Enumerable","problem_statement":"Enumerate source exactly once and return consecutive batches of at most capacity items; capacity must be positive. Do not emit an empty trailing batch.","difficulty":"Medium","topic_tags":["Generics and Enumeration","C#"],"constraints":["capacity is positive; source may be single-pass and contain up to 100000 items.","Enumerate source exactly once and omit an empty final batch."],"examples":[{"input":"[1,2,3,4,5],capacity=2","output":"[[1,2],[3,4],[5]]"},{"input":"[\"x\"],capacity=3","output":"[[\"x\"]]"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static List<List<T>> Batch<T>(IEnumerable<T> source,int capacity) {\n    // Batch a Single-Pass Enumerable.\n    return new List<List<T>>();\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"apply-payment-events-csharp","title":"Apply Payment Events Safely","problem_statement":"Apply changes in order. If any intermediate balance is negative return false and restore balance to initial; otherwise return true and the final balance.","difficulty":"Hard","topic_tags":["Decimal and State Modeling","C#"],"constraints":["Initial balance and changes are valid Decimal values; at most 100000 changes.","A negative intermediate balance fails atomically and restores the original balance."],"examples":[{"input":"10m,[-3m,5m]","output":"true,12m"},{"input":"2m,[-3m]","output":"false,2m"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static bool TryApplyPayments(decimal initial,decimal[] changes,out decimal balance) {\n    // Apply Payment Events Safely.\n    balance = initial; return false;\n  }\n}"},"points":200},{"collection_slug":"csharp-programming","slug":"sort-nullable-scores-csharp","title":"Sort Nullable Scores Stably","problem_statement":"Return a copy sorted by non-null scores descending, null scores last, retaining original order for equal scores and nulls.","difficulty":"Medium","topic_tags":["LINQ and Null Handling","C#"],"constraints":["At most 100000 rows; names are non-null strings.","Sort scores descending, place null last, and preserve original order on ties."],"examples":[{"input":"[(A,2),(B,null),(C,5),(D,2)]","output":"[(C,5),(A,2),(D,2),(B,null)]"},{"input":"[(X,null),(Y,1)]","output":"[(Y,1),(X,null)]"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static (string Name,int? Score)[] SortScores((string Name,int? Score)[] rows) {\n    // Sort Nullable Scores Stably.\n    return Array.Empty<(string Name,int? Score)>();\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"minimum-meeting-rooms-csharp","title":"Minimum Meeting Rooms","problem_statement":"Meetings are half-open [Start,End). Return the minimum rooms needed; a room can be reused when one meeting ends exactly as another starts. Ignore empty meetings.","difficulty":"Medium","topic_tags":["Sorting and Greedy Scheduling","C#"],"constraints":["At most 100000 valid half-open meetings with integer endpoints.","Ignore empty meetings; a room is reusable when end equals the next start."],"examples":[{"input":"[(0,30),(5,10),(15,20)]","output":"2"},{"input":"[(1,3),(3,5)]","output":"1"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static int MinimumMeetingRooms((int Start,int End)[] meetings) {\n    // Minimum Meeting Rooms.\n    return 0;\n  }\n}"},"points":150},{"collection_slug":"csharp-programming","slug":"expired-session-order-csharp","title":"Order Expired Sessions","problem_statement":"Select sessions whose expiration is at or before now and return IDs ordered by expiration ascending, then ordinal ID.","difficulty":"Medium","topic_tags":["LINQ and DateTimeOffset","C#"],"constraints":["At most 100000 sessions; IDs are non-null and expiration instants are UTC-offset aware.","Include expiration equal to now, then sort by instant and ordinal ID."],"examples":[{"input":"now=12:00; [(a,12:05),(b,11:00),(c,11:00)]","output":"[\"b\",\"c\"]"},{"input":"now=10:00; [(x,10:01)]","output":"[]"}],"starter_code_by_language":{"C#":"using System;\nusing System.Collections.Generic;\npublic static class Solution {\n  public static List<string> ExpiredSessionIds((string Id,DateTimeOffset ExpiresAt)[] sessions,DateTimeOffset now) {\n    // Order Expired Sessions.\n    return new List<string>();\n  }\n}"},"points":150}]$seed$) as s(collection_slug text,slug text,title text,problem_statement text,difficulty text,topic_tags text[],constraints jsonb,examples jsonb,starter_code_by_language jsonb,points integer);
do $validate_seed$ begin
if (select count(*) from coding_question_seed)<>20 or (select count(distinct slug) from coding_question_seed)<>20 or exists(select 1 from coding_question_seed where collection_slug<>'csharp-programming') then raise exception 'Expected exactly 20 unique C# question rows'; end if;
if exists(select 1 from coding_question_seed where slug in ('palindrome-check','sum-even-numbers','longest-word','merge-sorted-arrays','email-validation','count-positive-csharp','first-repeated-value-csharp')) then raise exception 'Existing C# slug collision'; end if;
if (select count(distinct title) from coding_question_seed)<>20 or exists(select 1 from coding_question_seed where char_length(btrim(title))<8 or char_length(btrim(problem_statement))<100 or difficulty not in ('Easy','Medium','Hard') or jsonb_typeof(constraints)<>'array' or jsonb_array_length(constraints)<2 or jsonb_typeof(examples)<>'array' or jsonb_array_length(examples)<2 or jsonb_typeof(starter_code_by_language)<>'object' or not starter_code_by_language ? 'C#' or points not between 0 and 1000 or problem_statement ~* '(named operation|input candidates|placeholder|TODO|implement the described transformation)') then raise exception 'C# completeness or placeholder validation failed'; end if;
if exists(select 1 from coding_question_seed q where exists(select 1 from jsonb_array_elements(q.examples) e where nullif(btrim(e->>'input'),'') is null or nullif(btrim(e->>'output'),'') is null or btrim(e->>'input') in ('[]','[null]','null'))) then raise exception 'C# examples must be meaningful input/output pairs'; end if;
if not exists(select 1 from public.coding_test_sets where slug='csharp-programming' and publication_status='published') then raise exception 'Published C# collection missing'; end if; end; $validate_seed$;
with question_rows as (select c.id collection_id,s.*,coalesce(m.max_order,0)+row_number() over(partition by c.id order by s.slug)::integer question_order from coding_question_seed s join public.coding_test_sets c on c.slug=s.collection_slug and c.publication_status='published' cross join lateral(select max(q.question_order) max_order from public.coding_questions q where q.collection_id=c.id) m) insert into public.coding_questions(collection_id,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points,publication_status,question_order) select collection_id,slug,title,problem_statement,difficulty,topic_tags,constraints,examples,starter_code_by_language,points,'published',question_order from question_rows on conflict(collection_id,slug) do nothing;
insert into public.coding_test_cases(question_id,case_order,test_input,expected_output,visibility) select q.id,e.ordinality::integer,e.value->>'input',e.value->>'output','visible' from coding_question_seed s join public.coding_test_sets c on c.slug=s.collection_slug join public.coding_questions q on q.collection_id=c.id and q.slug=s.slug cross join lateral jsonb_array_elements(s.examples) with ordinality e(value,ordinality) on conflict(question_id,case_order) do nothing;
commit;
